/** One Server-Sent Event, as `EventSource` would dispatch it. */
export interface SSEMessage {
  /** The `event:` field of the block, `message` when it has none. */
  event: string;
  /** The `data:` lines of the block joined with a line feed. */
  data: string;
  /** The last `id:` seen on the stream so far (kept across messages), `''` before the first. */
  id: string;
  /** A reconnection time in milliseconds sent since the previous message, when there was one. */
  retry?: number;
}

/** Incremental parser for the `text/event-stream` format (WHATWG HTML, "Server-sent events"). */
export interface EventStreamParser {
  /** Feeds decoded text and returns the messages it completed. Throws a RangeError past the limit. */
  write(text: string): SSEMessage[];
}

const DIGITS = /^[0-9]+$/;

export function createEventStreamParser(maxBufferSize: number): EventStreamParser {
  let line = ''; // text of the current line, not yet terminated
  let skipLineFeed = false; // the last line ended in CR; a following LF belongs to it
  let blockSize = 0; // characters of the lines of the current block, terminators included
  let event = '';
  let dataLines: string[] = [];
  let lastEventId = '';
  let retry: number | undefined;

  const tooLarge = () => new RangeError(`A pending event is longer than maxBufferSize (${maxBufferSize} characters).`);

  function field(raw: string) {
    if (raw.startsWith(':')) return;
    const colon = raw.indexOf(':');
    const name = colon === -1 ? raw : raw.slice(0, colon);
    let value = colon === -1 ? '' : raw.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (name === 'event') event = value;
    else if (name === 'data') dataLines.push(value);
    else if (name === 'id') {
      if (!value.includes('\u0000')) lastEventId = value;
    } else if (name === 'retry' && DIGITS.test(value)) {
      const ms = Number(value);
      if (Number.isSafeInteger(ms)) retry = ms;
    }
  }

  function dispatch(out: SSEMessage[]) {
    if (dataLines.length > 0) {
      const message: SSEMessage = { event: event || 'message', data: dataLines.join('\n'), id: lastEventId };
      if (retry !== undefined) {
        message.retry = retry;
        retry = undefined;
      }
      out.push(message);
    }
    event = '';
    dataLines = [];
    blockSize = 0;
  }

  function endLine(out: SSEMessage[]) {
    if (line === '') {
      dispatch(out);
      return;
    }
    blockSize += line.length + 1;
    if (blockSize > maxBufferSize) throw tooLarge();
    field(line);
    line = '';
  }

  return {
    write(text) {
      const out: SSEMessage[] = [];
      let start = 0;
      if (skipLineFeed && text !== '') {
        skipLineFeed = false;
        if (text.charCodeAt(0) === 10) start = 1;
      }
      for (let i = start; i < text.length; i++) {
        const code = text.charCodeAt(i);
        if (code !== 10 && code !== 13) continue;
        line += text.slice(start, i);
        endLine(out);
        line = '';
        start = i + 1;
        if (code === 13) {
          if (text.charCodeAt(start) === 10) {
            start++;
            i++;
          } else if (start === text.length) skipLineFeed = true;
        }
      }
      line += text.slice(start);
      if (blockSize + line.length > maxBufferSize) throw tooLarge();
      return out;
    },
  };
}

export {
  readSSE,
  readTextParts,
  type ReadSSEOptions,
  type ReadTextPartsOptions,
  type SSEMessage,
  type StreamSource,
} from './readSSE';
export { doc as readSSEDoc } from './readSSE.doc';

import { createEventStreamParser, type SSEMessage } from './eventStreamParser';
import { DEFAULT_MAX_BUFFER_SIZE, streamText, type StreamSource } from './streamText';

export type { SSEMessage } from './eventStreamParser';
export type { StreamSource } from './streamText';

export interface ReadSSEOptions {
  /** Aborting cancels the reader and makes the iterator throw `signal.reason` (an `AbortError` by default). */
  signal?: AbortSignal;
  /** Pending characters (decoded string length, not bytes) allowed in one block. Default 1,048,576. */
  maxBufferSize?: number;
}

export interface ReadTextPartsOptions extends ReadSSEOptions {
  /** Text that ends a part. Default a line feed. Must not be empty. */
  separator?: string;
}

/**
 * Reads a streamed `fetch` response as Server-Sent Events, following the WHATWG event-stream rules.
 * Use it where `EventSource` cannot be: POST bodies, auth headers, chat replies and log tails.
 *
 * - UTF-8 is decoded as a stream, so a character or a CR LF pair split across chunks is fine.
 * - A blank line dispatches a message. `event` defaults to `message`, repeated `data` lines are joined
 *   with a line feed, `id` persists across messages (an id containing U+0000 is ignored) and `retry`
 *   is kept only when it is all digits. Comment lines and unknown fields are ignored.
 * - A block without `data` yields nothing, but its `retry` is reported with the next message.
 * - An unterminated final block is dropped, as `EventSource` does. A server that closes without a blank
 *   line therefore loses its last message.
 * - It does not check `response.ok` or the content type, and does not reconnect: remember `id` and
 *   `retry` to reconnect with `Last-Event-ID`. A `Response` without a body throws a `TypeError`.
 * - Aborting `signal`, leaving the loop early (`break`, `return()`) or a stream error cancels the reader
 *   once, so the connection closes. The iterator throws `signal.reason` on abort.
 * - `maxBufferSize` bounds memory, not time: a stream that never sends a blank line stays open until
 *   you abort. A longer pending block throws a `RangeError` and cancels the reader.
 * - OpenAI-style streams end with `data: [DONE]`, which is yielded as plain data: stop on it yourself.
 *
 * @example
 * const controller = new AbortController();
 * const response = await fetch('/api/chat', { method: 'POST', body, signal: controller.signal });
 * for await (const message of readSSE(response, { signal: controller.signal })) {
 *   if (message.data === '[DONE]') break;
 *   append(JSON.parse(message.data));
 * }
 */
export async function* readSSE(source: StreamSource, options: ReadSSEOptions = {}): AsyncGenerator<SSEMessage> {
  const { signal, maxBufferSize = DEFAULT_MAX_BUFFER_SIZE } = options;
  const parser = createEventStreamParser(maxBufferSize);
  for await (const text of streamText(source, signal)) {
    for (const message of parser.write(text)) {
      if (signal?.aborted) throw signal.reason;
      yield message;
    }
  }
}

/**
 * Reads a streamed response as text parts split on `separator` (default a line feed), for protocols
 * that are not SSE, such as NDJSON log tails. Parts do not include the separator; empty parts are
 * skipped, and a part split across chunks (or a separator split across chunks) is joined. Text after
 * the last separator is yielded when the stream ends. Map parts in your loop (`JSON.parse(part)`).
 *
 * Abort, early exit, stream errors, `maxBufferSize` (a pending part longer than it throws a
 * `RangeError`) and a `Response` without a body behave as in {@link readSSE}.
 *
 * @example
 * for await (const line of readTextParts(response, { signal })) {
 *   log.push(JSON.parse(line));
 * }
 */
export async function* readTextParts(source: StreamSource, options: ReadTextPartsOptions = {}): AsyncGenerator<string> {
  const { signal, maxBufferSize = DEFAULT_MAX_BUFFER_SIZE, separator = '\n' } = options;
  if (separator === '') throw new TypeError('readTextParts: separator must not be empty.');
  const tooLarge = () => new RangeError(`A pending part is longer than maxBufferSize (${maxBufferSize} characters).`);
  let pending = '';
  for await (const text of streamText(source, signal)) {
    // A separator may straddle the previous chunk, so look again from its last few characters.
    let from = Math.max(0, pending.length - (separator.length - 1));
    pending += text;
    let start = 0;
    for (let end = pending.indexOf(separator, from); end !== -1; end = pending.indexOf(separator, from)) {
      if (end - start > maxBufferSize) throw tooLarge();
      const part = pending.slice(start, end);
      start = from = end + separator.length;
      if (part === '') continue;
      if (signal?.aborted) throw signal.reason;
      yield part;
    }
    pending = pending.slice(start);
    if (pending.length > maxBufferSize) throw tooLarge();
  }
  if (pending !== '') yield pending;
}

/** A fetch `Response` or the byte stream of one (`response.body`). */
export type StreamSource = Response | ReadableStream<Uint8Array>;

/** Default for `maxBufferSize`: pending characters allowed before a RangeError. */
export const DEFAULT_MAX_BUFFER_SIZE = 1_048_576;

const noop = () => {};

function bodyOf(source: StreamSource): ReadableStream<Uint8Array> {
  if ('getReader' in source) return source;
  if (source.body === null) throw new TypeError('The response has no body to read.');
  return source.body;
}

/**
 * Decoded text chunks of a byte stream. Owns the reader: it is cancelled exactly once when the
 * signal aborts, the consumer stops early or the stream fails, and only released when the stream ends.
 * Uses `getReader()` because `ReadableStream` is not async iterable in every browser.
 */
export async function* streamText(source: StreamSource, signal?: AbortSignal): AsyncGenerator<string> {
  const reader = bodyOf(source).getReader();
  const decoder = new TextDecoder();
  let ended = false;
  let cancelled = false;
  let interrupt: ((reason: unknown) => void) | undefined;

  const cancel = (reason?: unknown) => {
    if (cancelled) return;
    cancelled = true;
    try {
      Promise.resolve(reader.cancel(reason)).catch(noop);
    } catch {
      // A reader that cannot be cancelled has nothing left to release.
    }
  };
  const read = () =>
    new Promise<ReadableStreamReadResult<Uint8Array>>((resolve, reject) => {
      interrupt = reject;
      reader.read().then(resolve, reject);
    });
  const onAbort = () => {
    cancel(signal?.reason);
    interrupt?.(signal?.reason);
  };
  signal?.addEventListener('abort', onAbort, { once: true });

  try {
    for (;;) {
      if (signal?.aborted) throw signal.reason;
      const result = await read();
      if (signal?.aborted) throw signal.reason;
      if (result.done) {
        ended = true;
        break;
      }
      const text = decoder.decode(result.value, { stream: true });
      if (text) yield text;
    }
    const rest = decoder.decode();
    if (rest) yield rest;
  } finally {
    signal?.removeEventListener('abort', onAbort);
    if (!ended) cancel();
    try {
      reader.releaseLock();
    } catch {
      // Already released, or the reader is not lockable.
    }
  }
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'readSSE',
  group: 'Feedback',
  status: 'beta',
  description:
    'Reads a streamed fetch response as an async iterator, for chat replies and live log tails where EventSource cannot be used (POST bodies, auth headers). `readSSE(response, { signal, maxBufferSize })` follows the WHATWG event-stream rules: streaming UTF-8, BOM, CRLF/LF/CR endings across chunk boundaries, comments, multi-line data, a persistent id and a digits-only retry. `readTextParts` splits on a separator (a line feed by default) for NDJSON. Aborting the signal, leaving the loop early or a stream error cancels the reader once, so the connection closes. An unterminated final block is dropped, as EventSource does. There is no reconnection: keep the last id and retry and send Last-Event-ID yourself. maxBufferSize bounds memory, not time, so abort a stream that goes quiet.',
};
